 57		}
 58		if config.Skipper == nil {
 59			config.Skipper = DefaultBodyDumpConfig.Skipper
 60		}
 61	
 62		return func(next echo.HandlerFunc) echo.HandlerFunc {
 63			return func(c echo.Context) (err error) {
 64				if config.Skipper(c) {
 65					return next(c)
 66				}
 67	
 68				// Request
 69				reqBody := []byte{}
 70				if c.Request().Body != nil { // Read
 71					reqBody, _ = ioutil.ReadAll(c.Request().Body)
 72				}
 73				c.Request().Body = ioutil.NopCloser(bytes.NewBuffer(reqBody)) // Reset
 74	
 75				// Response
