 77				mw := io.MultiWriter(c.Response().Writer, resBody)
 78				writer := &bodyDumpResponseWriter{Writer: mw, ResponseWriter: c.Response().Writer}
 79				c.Response().Writer = writer
 80	
 81				if err = next(c); err != nil {
 82					c.Error(err)
 83				}
 84	
 85				// Callback
 86				config.Handler(c, reqBody, resBody.Bytes())
 87	
 88				return
 89			}
 90		}
 91	}
