## Bug found
`/echo/context.go`, `func (c *context) Scheme()` (lines 252–271). The forwarded-header values were returned **unvalidated** — any non-empty value was trusted, so an invalid `X-Forwarded-Proto` was returned verbatim instead of being ignored, and it never fell through to `X-Forwarded-Protocol`.

Before (lines 258–269):
```go
	if scheme := c.request.Header.Get(HeaderXForwardedProto); scheme != "" {
		return scheme
	}
	if scheme := c.request.Header.Get(HeaderXForwardedProtocol); scheme != "" {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := c.request.Header.Get(HeaderXUrlScheme); scheme != "" {
		return scheme
	}
	return "http"
```
i.e. `X-Forwarded-Proto: invalid` returned `"invalid"` instead of falling back to `X-Forwarded-Protocol` / `http`.

## Patch applied (context.go, now lines 252–283)
```go
	if scheme := c.request.Header.Get(HeaderXForwardedProto); isValidScheme(scheme) {
		return scheme
	}
	if scheme := c.request.Header.Get(HeaderXForwardedProtocol); isValidScheme(scheme) {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := c.request.Header.Get(HeaderXUrlScheme); isValidScheme(scheme) {
		return scheme
	}
	return "http"
}

// isValidScheme reports whether scheme is a known HTTP or WebSocket scheme.
// Values forwarded by proxies (X-Forwarded-Proto, X-Forwarded-Protocol,
// X-Url-Scheme) are only trusted when they are one of these, otherwise a
// client could spoof the scheme with an arbitrary header value.
func isValidScheme(scheme string) bool {
	switch strings.ToLower(scheme) {
	case "http", "https", "ws", "wss":
		return true
	default:
		return false
	}
}
