package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

// ---- clean-room reference matcher for echo route patterns ----
// pattern segments: static, ":param" (one non-empty segment), "*" (rest, must be last)
func refMatch(pattern, path string) bool {
	if !strings.HasPrefix(path, "/") {
		return false
	}
	ps := strings.Split(pattern, "/") // leading "" for leading '/'
	xs := strings.Split(path, "/")
	// both start with "" (leading slash)
	for i := 0; i < len(ps); i++ {
		if ps[i] == "*" {
			// '*' consumes the rest of the path; requires the '/' separator to be present
			// i.e. there must be at least one more segment in the path than consumed so far
			if i >= len(xs) {
				return false
			}
			return true
		}
		if i >= len(xs) {
			return false
		}
		if strings.HasPrefix(ps[i], ":") {
			if xs[i] == "" {
				return false
			}
			continue
		}
		if ps[i] != xs[i] {
			return false
		}
	}
	return len(ps) == len(xs)
}

var fuzzSegs = []string{"a", "b", "ab", "abc", "c"}
var fuzzReqSegs = []string{"a", "b", "ab", "abc", "c", "x", "abx"}

func randPattern(rnd *rand.Rand) string {
	n := 1 + rnd.Intn(3)
	var b strings.Builder
	for i := 0; i < n; i++ {
		b.WriteString("/")
		switch rnd.Intn(4) {
		case 0:
			b.WriteString(":" + string(rune('p'+i)))
		default:
			b.WriteString(fuzzSegs[rnd.Intn(len(fuzzSegs))])
		}
	}
	if rnd.Intn(4) == 0 {
		b.WriteString("/*")
	}
	return b.String()
}

func randPath(rnd *rand.Rand) string {
	n := rnd.Intn(5)
	var b strings.Builder
	for i := 0; i < n; i++ {
		b.WriteString("/")
		b.WriteString(fuzzReqSegs[rnd.Intn(len(fuzzReqSegs))])
	}
	if n == 0 {
		return "/"
	}
	if rnd.Intn(5) == 0 {
		b.WriteString("/")
	}
	return b.String()
}

func TestZZTmpFuzzOracle(t *testing.T) {
	rnd := rand.New(rand.NewSource(7))
	panics, falseNotFound, falseMatch := 0, 0, 0
	for iter := 0; iter < 20000; iter++ {
		e := New()
		r := e.router
		n := 1 + rnd.Intn(4)
		used := map[string]bool{}
		var added []string
		for i := 0; i < n; i++ {
			p := randPattern(rnd)
			if used[p] {
				continue
			}
			used[p] = true
			added = append(added, p)
			r.Add(http.MethodGet, p, handlerFunc)
		}
		for j := 0; j < 6; j++ {
			req := randPath(rnd)
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						panics++
						if panics < 10 {
							t.Errorf("PANIC routes=%v req=%q: %v", added, req, rec)
						}
					}
				}()
				c := e.NewContext(nil, nil).(*context)
				r.Find(http.MethodGet, req, c)
				h := c.Handler()
				if h == nil {
					panics++
					if panics < 10 {
						t.Errorf("NIL HANDLER routes=%v req=%q", added, req)
					}
					return
				}
				matched := false
				for _, p := range added {
					if refMatch(p, req) {
						matched = true
						break
					}
				}
				isNotFound := h(c) == ErrNotFound
				if matched && isNotFound {
					falseNotFound++
					if falseNotFound < 10 {
						t.Errorf("FALSE 404 routes=%v req=%q (ctx.path=%q)", added, req, c.path)
					}
				}
				if !matched && !isNotFound {
					falseMatch++
					if falseMatch < 10 {
						t.Errorf("FALSE MATCH routes=%v req=%q -> ctx.path=%q", added, req, c.path)
					}
				}
				if matched && !isNotFound {
					// returned route pattern must itself match the request
					if !refMatch(c.path, req) {
						falseMatch++
						if falseMatch < 10 {
							t.Errorf("WRONG ROUTE routes=%v req=%q -> ctx.path=%q", added, req, c.path)
						}
					}
				}
			}()
		}
	}
	fmt.Printf("panics=%d falseNotFound=%d falseMatch=%d\n", panics, falseNotFound, falseMatch)
}
EOF
