			givenMethod:      http.MethodPost,
			givenContentType: MIMEApplicationForm,
			givenContent:     strings.NewReader(`id=1&node=yyy`),
			whenBindTarget:   &map[string]interface{}{},
			expect:           map[string]interface{}{"id": "1", "node": "yyy"},
		},
		{
			name:             "ok, bind to map[string]string",
			givenURL:         "/api/real_node/endpoint?node=xxx",
			givenMethod:      http.MethodPost,
			givenContentType: MIMEApplicationForm,
			givenContent:     strings.NewReader(`id=1&node=yyy`),
			whenBindTarget:   &map[string]string{},
			expect:           map[string]string{"id": "1", "node": "yyy"},
		},
		{
			name:             "ok, bind to map[string][]string",
			givenURL:         "/api/real_node/endpoint?node=xxx",
			givenMethod:      http.MethodPost,
			givenContentType: MIMEApplicationForm,
			givenContent:     strings.NewReader(`id=1&id=2&node=yyy`),
			whenBindTarget:   &map[string][]string{},
			expect:           map[string][]string{"id": {"1", "2"}, "node": {"yyy"}},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			e := New()
			req := httptest.NewRequest(tc.givenMethod, tc.givenURL, tc.givenContent)
			req.Header.Set(HeaderContentType, tc.givenContentType)
			rec := httptest.NewRecorder()
			c := e.NewContext(req, rec)

			b := new(DefaultBinder)
			err := b.BindBody(c, tc.whenBindTarget)
			if tc.expectError != "" {
				assert.EqualError(t, err, tc.expectError)
			} else {
				assert.NoError(t, err)
			}
			assert.Equal(t, tc.expect, tc.whenBindTarget)
		})
	}
}

